// Program.cs — Entry Point
var builder = WebApplication.CreateBuilder(args);

// Register services into DI container
builder.Services.AddControllers();
builder.Services.AddDbContext<MissionDbContext>(options =>
  options.UseSqlServer(builder.Configuration.GetConnectionString("Default")));
builder.Services.AddScoped<IMissionService, MissionService>();

var app = builder.Build();

// Configure middleware pipeline
app.UseHttpsRedirection();
app.UseAuthentication();
app.UseAuthorization();
app.MapControllers();

app.Run();

[ApiController]
[Route("api/[controller]")]
public class MissionsController : ControllerBase
{
  private readonly IMissionService _missions;

  public MissionsController(IMissionService missions)
  {
    _missions = missions; // Injected by DI
  }

  [HttpGet]                          // GET /api/missions
  public async Task<IActionResult> GetAll()
    => Ok(await _missions.GetAllAsync());

  [HttpGet("{id}")]                  // GET /api/missions/5
  public async Task<IActionResult> GetById(int id)
    => Ok(await _missions.GetByIdAsync(id));

  [HttpPost]                         // POST /api/missions
  public async Task<IActionResult> Create([FromBody] MissionDto dto)
    => CreatedAtAction(nameof(GetById), new { id = dto.Id }, dto);
}

// Entity model
public class Mission {
  public int Id { get; set; }
  public string Name { get; set; } = string.Empty;
  public string Status { get; set; } = "Active";
  public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
}

// DbContext
public class MissionDbContext : DbContext {
  public MissionDbContext(DbContextOptions<MissionDbContext> options)
    : base(options) { }
  public DbSet<Mission> Missions => Set<Mission>();
}

// Service usage with LINQ
public async Task<List<Mission>> GetActiveAsync()
  => await _context.Missions
    .Where(m => m.Status == "Active")
    .OrderByDescending(m => m.CreatedAt)
    .ToListAsync();

// Register JWT auth in Program.cs
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
  .AddJwtBearer(options => {
    options.TokenValidationParameters = new() {
      ValidateIssuerSigningKey = true,
      IssuerSigningKey = new SymmetricSecurityKey(
        Encoding.UTF8.GetBytes(builder.Configuration["Jwt:Secret"]!)),
      ValidateIssuer = false,
      ValidateAudience = false
    };
  });

// Protect a controller
[Authorize(Roles = "Admin,Pilot")]
[ApiController]
[Route("api/[controller]")]
public class SecretMissionsController : ControllerBase { }

// Minimal API — entire API in Program.cs!
var app = builder.Build();

// GET /api/missions
app.MapGet("/api/missions", async (MissionDbContext db) =>
  await db.Missions.ToListAsync());

// GET /api/missions/{id}
app.MapGet("/api/missions/{id}", async (int id, MissionDbContext db) =>
  await db.Missions.FindAsync(id)
    is Mission m ? Results.Ok(m) : Results.NotFound());

// POST /api/missions
app.MapPost("/api/missions", async (Mission m, MissionDbContext db) => {
  db.Missions.Add(m);
  await db.SaveChangesAsync();
  return Results.Created($"/api/missions/{m.Id}", m);
}).RequireAuthorization();

app.Run();

// Custom Exception Handling Middleware
public class ErrorHandlingMiddleware {
  private readonly RequestDelegate _next;
  private readonly ILogger _logger;

  public ErrorHandlingMiddleware(RequestDelegate next,
    ILogger<ErrorHandlingMiddleware> logger) {
    _next = next; _logger = logger;
  }

  public async Task InvokeAsync(HttpContext ctx) {
    try {
      await _next(ctx);
    } catch (Exception ex) {
      _logger.LogError(ex, "Unhandled exception");
      ctx.Response.StatusCode = 500;
      ctx.Response.ContentType = "application/json";
      await ctx.Response.WriteAsJsonAsync(new {
        status = 500, title = "Server Error",
        detail = "An internal error occurred."
      });
    }
  }
}
